1	/**
2	 * Fixtures for the server suite: a throwaway SQLite file plus a helper that
3	 * builds one fully-populated tenant (org, four members, a project) through the
4	 * real repositories, so the rows under test are the rows production writes.
5	 *
6	 * Kept apart from `tests/helpers/*` — those belong to another owner.
7	 */
8	import { mkdtempSync, rmSync } from "node:fs";
9	import { tmpdir } from "node:os";
10	import { join } from "node:path";
11	import { runMigrations } from "@/server/db/migrate";
12	import * as memberRepo from "@/server/repositories/member-repository";
13	import * as orgRepo from "@/server/repositories/organization-repository";
14	import * as projectRepo from "@/server/repositories/project-repository";
15	import * as subscriptionRepo from "@/server/repositories/subscription-repository";
16	import * as userRepo from "@/server/repositories/user-repository";
17	import type { PlanId } from "@/types/billing";
18	import type { OrgId, UserId } from "@/types/common";
19	import type { Actor, Role } from "@/types/member";
20	import type { Organization } from "@/types/organization";
21	import type { Project } from "@/types/project";
22	
23	export interface Tenant {
24	  readonly org: Organization;
25	  readonly project: Project;
26	  readonly actors: Readonly<Record<Role, Actor>>;
27	  readonly userIds: Readonly<Record<Role, UserId>>;
28	}
29	
30	const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];
31	
32	/**
33	 * Points the connection at a fresh database file and migrates it. Call from
34	 * `beforeAll`; the returned function removes the directory again.
35	 *
36	 * A file rather than `:memory:` because `runMigrations` and the app client
37	 * open separate connections, and only a file is shared between the two.
38	 */
39	export async function useTemporaryDatabase(): Promise<() => void> {
40	  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
41	  const path = join(dir, "taskflow.db");
42	
43	  process.env.TASKFLOW_DB_PATH = path;
44	  await runMigrations(path);
45	
46	  return () => {
47	    rmSync(dir, { recursive: true, force: true });
48	  };
49	}
50	
51	/**
52	 * Creates one organization with a member in every role and a single project.
53	 * `plan` decides which quotas apply — the free plan's three seats is what the
54	 * invite-limit test leans on.
55	 */
56	export async function createTenant(
57	  slug: string,
58	  plan: PlanId = "growth",
59	): Promise<Tenant> {
60	  const owner = await userRepo.insertUser({
61	    email: `owner@${slug}.test`,
62	    name: `${slug} owner`,
63	    passwordHash: "seed",
64	  });
65	
66	  const org = await orgRepo.insertOrg(
67	    { name: `${slug} inc`, slug, plan },
68	    owner.id,
69	  );
70	
71	  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");
72	
73	  const userIds: Partial<Record<Role, UserId>> = {};
74	  const actors: Partial<Record<Role, Actor>> = {};
75	
76	  for (const role of ROLES) {
77	    const user =
78	      role === "owner"
79	        ? owner
80	        : await userRepo.insertUser({
81	            email: `${role}@${slug}.test`,
82	            name: `${slug} ${role}`,
83	            passwordHash: "seed",
